require_once 'config/koneksi.php';require_once 'includes/functions.php';$kode=$_GET['kode']??'';$stmt=$conn->prepare("SELECT ps.*,pb.nama,pb.email,pb.alamat FROM pesanan ps JOIN pembeli pb ON pb.id_pembeli=ps.id_pembeli WHERE ps.kode_pesanan=?");$stmt->bind_param('s',$kode);$stmt->execute();$ps=$stmt->get_result()->fetch_assoc();if(!$ps)redirect('index.php');$stmt=$conn->prepare("SELECT d.*,p.nama_produk FROM detail_pesanan d JOIN produk p ON p.id_produk=d.id_produk WHERE d.id_pesanan=?");$stmt->bind_param('i',$ps['id_pesanan']);$stmt->execute();$det=$stmt->get_result();$judul='Pesanan berhasil';include 'includes/header.php';?>
